/** Events */
export const events = {
	repositoriesRequested: makeEvent<RepositoriesRequested, RepositoriesRequested>("repositories-requested"),
	repositoryChanged: makeEvent<RepositoryChanged, RepositoryChanged>("repository-changed"),
};

/* Types */
/**  Commits one side has that the other lacks. */
export type AheadBehindDto = {
	/**  Commits of the target that the base lacks. */
	ahead: number,
	/**  Commits of the base that the target lacks. */
	behind: number,
};

/**  Serializable error returned by every fallible Tauri command. */
export type AppError = {
	/**  Category used by the UI to pick an icon, retry policy, etc. */
	code: ErrorCode,
	/**  What happened, phrased for an end user. */
	message: string,
	/**  What the user can do next, if there is anything useful to suggest. */
	hint: string | null,
};

/**  Name, version and platform of the running app, shown in the status bar and About dialog. */
export type AppInfo = {
	/**  Product name from `tauri.conf.json`. */
	name: string,
	/**  Semantic version from `tauri.conf.json`. */
	version: string,
	/**  Operating system family, e.g. `windows`, `macos`, `linux`. */
	os: string,
	/**  CPU architecture, e.g. `x86_64`, `aarch64`. */
	arch: string,
};

/**  What applying did. */
export type ApplyOutcomeDto = {
	/**  What git printed. */
	output: string,
	/**  It applied with merge conflicts, now in the working tree; a pop kept the stash. */
	conflicts: boolean,
};

/**  Applying some files of a stash. */
export type ApplyStashFilesRequestDto = {
	/**  The stash commit's full id (hex). */
	id: string,
	/**  Tracked files, as listed in `changed` (both names of a rename). */
	tracked: string[],
	/**  Untracked files, as listed in `untracked`. */
	untracked: string[],
};

/**  Applying or popping a whole stash. */
export type ApplyStashRequestDto = {
	/**  Which stash. */
	stash: StashTargetDto,
	/**  Drop it after applying without conflicts (`git stash pop`). */
	pop: boolean,
	/**  Also restore what was staged (`--index`). */
	restoreIndex: boolean,
};

/**  A commit some lines come from. */
export type BlameCommitDto = {
	/**  Full commit id. */
	id: string,
	/**  First line of the message. */
	summary: string,
	/**  Author name (after `.mailmap`). */
	authorName: string,
	/**  Author e-mail. */
	authorEmail: string,
	/**  Author time in seconds since the epoch. */
	authorTime: number | null,
	/**  What "blame the previous revision" opens; `null` when the commit added the file. */
	previous: BlamePreviousDto | null,
};

/**  The blame of a file at a commit. */
export type BlameDto = {
	/**  The file's blob in the commit (hex), for its lines; `null` for a submodule. */
	blobId: string | null,
	/**  Ordered by line, covering every line. */
	hunks: BlameHunkDto[],
	/**  The commits the hunks name. */
	commits: BlameCommitDto[],
	/**  The paths the hunks name (lossy for non-UTF-8 bytes). */
	paths: string[],
};

/**  Consecutive lines from one commit. */
export type BlameHunkDto = {
	/**  First line (1-based). */
	line: number,
	/**  Number of lines. */
	count: number,
	/**  Index into `commits`. */
	commit: number,
	/**  First line in that commit's version of the file (1-based). */
	originalLine: number,
	/**  Index into `paths`: the file's path in that commit. */
	path: number,
};

/**  The version of the file before a commit changed it. */
export type BlamePreviousDto = {
	/**  The parent commit (hex). */
	id: string,
	/**  The file's path there (it differs after a rename). */
	path: string,
};

/**  How the Branches module orders the refs of a section. */
export type BranchSort = 
/**  Alphabetically. */
"name" | 
/**  Newest commit first. */
"lastCommit";

/**  Branches module preferences. */
export type BranchesSettings = {
	/**  Order of the branches and tags in each section. */
	sort?: BranchSort,
};

/**  How a file changed. */
export type ChangeStatusDto = 
/**  New file. */
"added" | 
/**  Removed file. */
"deleted" | 
/**  Content or mode changed. */
"modified" | 
/**  Moved (`previousPath` is the old name). */
"renamed" | 
/**  Copied from `previousPath`. */
"copied";

/**
 *  One changed file. Paths are for display (non-UTF-8 bytes are replaced); the blob ids
 *  identify the contents without a round trip through the path.
 */
export type ChangedFileDto = {
	/**  Path after the change (before it, for deletions). */
	path: string,
	/**  Old path of a rename or copy. */
	previousPath: string | null,
	/**  How it changed. */
	status: ChangeStatusDto,
	/**  Blob before the change (hex); `null` when added. */
	oldId: string | null,
	/**  Blob after the change (hex); `null` when deleted. */
	newId: string | null,
	/**  A submodule pointer, not a file. */
	submodule: boolean,
};

/**  The changed files of one commit against one parent. */
export type ChangedFilesDto = {
	/**  Sorted by path, at most 5,000. */
	files: ChangedFileDto[],
	/**  All changed files, including those not listed. */
	total: number,
	/**  Parents of the commit (more than one for a merge; 0 for the first commit). */
	parentCount: number,
};

/**
 *  What the message box needs before the user types: who commits, the template, the comment
 *  character.
 */
export type CommitDefaultsDto = {
	/**  The configured author as `Name <email>`; `null` when no name or address is set. */
	author: string | null,
	/**  The configured `commit.template`, if any. */
	template: CommitTemplateDto | null,
	/**  The character starting comment lines (`core.commentChar`). */
	commentChar: string,
};

/**  Everything the Commit details module shows. */
export type CommitDetailsDto = {
	/**  Row in the graph. */
	row: number,
	/**  Full commit id. */
	id: string,
	/**  Parents, first parent first. */
	parents: CommitLinkDto[],
	/**  Commits that have this one as a parent, newest first. */
	children: CommitLinkDto[],
	/**  Who wrote the change. */
	author: SignatureDto,
	/**  Who created the commit. */
	committer: SignatureDto,
	/**  Whole message. */
	message: string,
	/**
	 *  What the commit is signed with; `null` when it is not signed
	 *  (`verify_commit_signature` checks it).
	 */
	signature: SignatureFormatDto | null,
	/**  References pointing at the commit. */
	refs: RefLabel[],
	/**  References containing the commit (at most 500). */
	containedIn: RefLabel[],
	/**  How many references contain the commit in total. */
	containedInTotal: number,
};

/**  A parent or child commit and its row, so the UI can jump to it. */
export type CommitLinkDto = {
	/**  Full commit id. */
	id: string,
	/**  Row in the graph; `None` when the tab's filter hides it. */
	row: number | null,
};

/**  A commit to make from the staged changes. */
export type CommitRequestDto = {
	/**  The message as typed (git applies `commit.cleanup`). */
	message: string,
	/**  Replace the last commit instead of adding one. */
	amend: boolean,
	/**  Add a `Signed-off-by` trailer. */
	signOff: boolean,
	/**  Someone else as the author, written `Name <email>`; `null`: the configured author. */
	author: string | null,
	/**  Leave out comment lines: the message started from `commit.template`. */
	stripComments: boolean,
};

/**  A commit that was made. */
export type CommitResultDto = {
	/**  What git and its hooks printed (git's summary line, hook messages). */
	output: string,
};

/**  Text columns of one graph row. */
export type CommitRowDto = {
	/**  Row number. */
	row: number,
	/**  Full commit id. */
	id: string,
	/**  First line of the message. */
	summary: string,
	/**  Author name. */
	authorName: string,
	/**  Author e-mail. */
	authorEmail: string,
	/**  Author time, seconds since the epoch. */
	authorTime: number | null,
	/**  Number of parents. */
	parentCount: number,
	/**  References pointing here. */
	refs: RefLabel[],
	/**  Stashes made on this commit (it is their base), newest first. */
	stashes: StashLabel[],
};

/**  The configured `commit.template`: its text, or why it could not be read. */
export type CommitTemplateDto = {
	/**  Where it is. */
	path: string,
	/**  Its text (lossy UTF-8); `null` when it could not be read. */
	text: string | null,
	/**  Why it could not be read. */
	problem: string | null,
};

/**  What to compare: two revisions as typed or picked (a branch, tag, commit id, `HEAD~2`). */
export type CompareRequestDto = {
	/**  The revision compared from. */
	base: string,
	/**  The revision compared to; ignored when `worktree` is set. */
	target: string,
	/**
	 *  Compare from the commits' merge base instead of from `base` (`git diff base...target`):
	 *  only what `target` changed since the two split.
	 */
	sinceMergeBase: boolean,
	/**
	 *  Compare to the working tree instead of `target` (`git diff base`); the merge base is then
	 *  the one of `base` and HEAD.
	 */
	worktree: boolean,
};

/**  One of the compared commits. */
export type ComparedCommitDto = {
	/**  Full commit id. */
	id: string,
	/**  First line of the message. */
	summary: string,
	/**  Author name. */
	authorName: string,
	/**  Author time in seconds since the epoch. */
	authorTime: number | null,
};

/**  The files that differ between two revisions. */
export type ComparisonDto = {
	/**  The commit `base` names. */
	base: ComparedCommitDto,
	/**  The commit `target` names; HEAD when compared with the working tree. */
	target: ComparedCommitDto,
	/**  The merge base the files are compared from; `null` when compared directly. */
	mergeBase: ComparedCommitDto | null,
	/**
	 *  Sorted by path, at most 100,000. Compared with the working tree, the new side of a file
	 *  that is not deleted is the file on disk (no `newId`), except for submodules.
	 */
	files: ChangedFileDto[],
	/**  All files that differ, including those not listed. */
	total: number,
	/**  Renames were found only between identical files (a partial clone lacks the contents). */
	exactRenamesOnly: boolean,
	/**  The second side is the working tree. */
	worktree: boolean,
};

/**  How dates are shown in the commit list. */
export type DateDisplay = 
/**  Date and time. */
"absolute" | 
/**  Time since, like "3 h ago" (the date and time in the tooltip). */
"relative";

/**  How a file was compared. */
export type DiffContentDto = 
/**  Line by line. */
"text" | 
/**  Binary contents: only the sizes. */
"binary" | 
/**  Larger than 64 MiB: only the sizes. */
"tooLarge";

/**  How the diff tab lays out a diff. */
export type DiffLayout = 
/**  One column, removed lines above added ones (`git diff`). */
"unified" | 
/**  Old version on the left, new version on the right. */
"split";

/**  One row of the unified diff. */
export type DiffLineDto = {
	/**  What the row shows. */
	kind: DiffLineKindDto,
	/**  1-based line number in the old version. */
	oldLine: number | null,
	/**  1-based line number in the new version. */
	newLine: number | null,
	/**  The line without its line ending (non-UTF-8 bytes replaced). */
	text: string,
	/**  The line was cut at 4,096 bytes. */
	truncated: boolean,
	/**  Changed words of a removed or added line: `[start, end)` in UTF-16 code units. */
	highlights: ([number, number])[],
	/**  Syntax colours: `[start, end, class]` in UTF-16 code units. */
	syntax: ([number, number, SyntaxClassDto])[],
};

/**  What a row shows. */
export type DiffLineKindDto = 
/**  `@@ -1,3 +1,4 @@` (in `text`). */
"hunk" | 
/**  Unchanged line. */
"context" | 
/**  Added line. */
"added" | 
/**  Removed line. */
"removed" | 
/**  "No newline at end of file" for the row above (empty `text`). */
"noNewline";

/**  How the diff is computed (the diff tab sends its settings). */
export type DiffOptionsDto = {
	/**  Which whitespace changes count. */
	whitespace: WhitespaceMode,
	/**  Unchanged lines around each change; 4294967295 for the whole file. */
	context: number,
	/**  Colour the code by the language of the path. */
	syntax: boolean,
};

/**  Which file diff a command is about. */
export type DiffRequestDto = {
	/**  Blob before the change (hex); `null` when the file is absent there. */
	oldId: string | null,
	/**  Blob after the change (hex); `null` when the file is absent there. */
	newId: string | null,
	/**  The file's path (its `.gitattributes` decide between text and binary). */
	path: string | null,
	/**  How to compare. */
	options: DiffOptionsDto,
	/**
	 *  The new side is the working tree file at `path`, and `new_id` the id
	 *  `get_worktree_file_id` gave it.
	 */
	worktree?: boolean,
};

/**  Diff tab preferences. */
export type DiffSettings = {
	/**  Unified or side by side. */
	layout?: DiffLayout,
	/**  Which whitespace changes are shown. */
	whitespace?: WhitespaceMode,
	/**
	 *  Unchanged lines around each change, unless `whole_file` is set (4294967295, written by
	 *  earlier versions, also means the whole file).
	 */
	contextLines?: number,
	/**  Show the whole file instead of the context lines. */
	wholeFile?: boolean,
	/**  Colour the code by its language. */
	syntaxHighlighting?: boolean,
};

/**  Stable, machine-readable error category the frontend can branch on. */
export type ErrorCode = 
/**  An unexpected failure inside the app; usually a bug. */
"INTERNAL" | 
/**  Reading or writing a local file failed. */
"IO" | 
/**  Data on disk could not be parsed. */
"INVALID_DATA" | 
/**  The input from the user or the command line is incomplete or contradictory. */
"INVALID_INPUT" | 
/**  The requested item does not exist. */
"NOT_FOUND" | 
/**  No `git` executable was found. */
"GIT_NOT_FOUND" | 
/**  A `git` executable was found but cannot be used (broken install, too old, ...). */
"GIT_UNUSABLE" | 
/**  A git command failed; the message carries git's own explanation. */
"GIT_FAILED" | 
/**  The user cancelled the operation. */
"CANCELLED" | 
/**  The folder is not inside a Git repository. */
"NOT_A_REPOSITORY" | 
/**  Git refuses the repository (owned by another user, not in `safe.directory`). */
"UNTRUSTED_REPOSITORY";

/**  What the diff tab needs before it asks for rows. */
export type FileDiffDto = {
	/**  How the file was compared. */
	content: DiffContentDto,
	/**  Rows of the unified diff, hunk headers included (fetch them with `get_diff_lines`). */
	rows: number,
	/**  Rows of the side-by-side diff (fetch them with `get_split_diff_lines`). */
	splitRows: number,
	/**  Added lines. */
	additions: number,
	/**  Removed lines. */
	deletions: number,
	/**  Number of hunks. */
	hunks: number,
	/**  Lines of the old version (0 unless compared as text). */
	oldLines: number,
	/**  Lines of the new version (0 unless compared as text). */
	newLines: number,
	/**  Size of the old version in bytes, as a decimal string (0 when absent). */
	oldSize: string,
	/**  Size of the new version in bytes, as a decimal string (0 when absent). */
	newSize: string,
};

/**  A path's history: how many commits, its earlier names, and whether it is complete. */
export type FileHistoryDto = {
	/**  Commits in the history. */
	total: number,
	/**  The names the file had before, as found (lossy for non-UTF-8 bytes). */
	previousNames: string[],
	/**  Set when renames were not followed to the file's first commit. */
	stopped: HistoryStopDto | null,
};

/**  One commit of a history. */
export type FileHistoryRowDto = {
	/**  Full commit id (hex). */
	id: string,
	/**  Its row in the graph the tab shows; `null` when the filter hides it. */
	row: number | null,
	/**  The file's path in this commit. */
	path: string,
	/**  What the commit did to it. */
	change: PathChangeDto,
	/**  For a rename, the name before. */
	previousPath: string | null,
	/**  First line of the message. */
	summary: string,
	/**  Author name. */
	authorName: string,
	/**  Author e-mail. */
	authorEmail: string,
	/**  Author time in seconds since the epoch. */
	authorTime: number | null,
};

/**  Which file a file view shows. */
export type FileViewRequestDto = {
	/**  The file's blob (hex). */
	blobId: string,
	/**  Its path (its `.gitattributes` and language apply). */
	path: string,
	/**  Colour the code by the language of the path. */
	syntax: boolean,
};

/**  One match of the find bar. */
export type FoundCommit = {
	/**  Row of the match; `None` when nothing matches. */
	row: number | null,
	/**  Its number among the matches, from 1 (0 when nothing matches). */
	position: number,
	/**  How many rows match. */
	total: number,
};

/**  The git executable NoBlame will run, shown in the status bar and About dialog. */
export type GitInfo = {
	/**  Absolute path of the executable (for display). */
	path: string,
	/**  Detected version, e.g. `2.47.1`. */
	version: string,
	/**  Whether the version is at least [`minimum_version`](Self::minimum_version). */
	supported: boolean,
	/**  Oldest version NoBlame supports. */
	minimumVersion: string,
};

/**  The commit a revision names and where it is. */
export type GoToCommit = {
	/**  Full commit id. */
	id: string,
	/**  Its row, when shown. */
	row: number | null,
	/**  Whether and why it is (not) shown. */
	status: GoToStatus,
};

/**  Where "go to commit" found a commit. */
export type GoToStatus = 
/**  On `row`. */
"shown" | 
/**  In the history, but hidden by the tab's filter. */
"hiddenByFilter" | 
/**  Not reachable from any branch, tag or HEAD (a stash, a dangling commit). */
"notInGraph";

/**  One column's place, visibility and width. */
export type GraphColumn = {
	/**  Which column. */
	id: GraphColumnId,
	/**  Shown (the message is always shown). */
	visible: boolean,
	/**
	 *  Width in pixels; unset (`null`) for the default: the graph fits its lanes, the message
	 *  always takes the rest.
	 */
	width: number | null,
};

/**  A column of the commit list. */
export type GraphColumnId = 
/**  Lanes and commit nodes. */
"graph" | 
/**  Ref labels and the first line of the message. */
"message" | 
/**  Author name. */
"author" | 
/**  Author date. */
"date" | 
/**  Short commit id. */
"commit";

/**  What a repository tab shows. */
export type GraphFilterDto = {
	/**  Whose history. */
	tips: TipsDto,
	/**  Follow first parents only. */
	firstParent: boolean,
	/**  Leave merges out. */
	noMerges: boolean,
	/**  Part of the author's name or e-mail, ignoring case; `null` or blank for any author. */
	author: string | null,
	/**  Part of the message, ignoring case; `null` or blank for any message. */
	message: string | null,
	/**
	 *  Only commits changing this file or folder, relative to the top of the working tree (a
	 *  git pathspec, so `*.rs` works); `null` or blank for any.
	 */
	path: string | null,
};

/**  Commit graph preferences. */
export type GraphSettings = {
	/**  Selecting a commit highlights its history and the commits by the same author. */
	highlightSelection?: boolean,
	/**  Where staged and unstaged changes are shown. */
	workingTree?: WorkingTreeDisplay,
	/**
	 *  The columns in display order, shown or not, with their widths. The UI keeps the graph
	 *  first and the message shown, ignores repeats and adds missing columns at the end.
	 */
	columns?: GraphColumn[],
	/**  Dates as a date and time, or as the time since ("3 h ago"). */
	dateDisplay?: DateDisplay,
};

/**  Size and shape of a loaded graph. */
export type GraphSummary = {
	/**  Number of rows (commits shown). */
	rows: number,
	/**  Number of commits without the filter. */
	totalRows: number,
	/**  What the tab shows. */
	filter: GraphFilterDto,
	/**  Widest lane count. */
	maxLanes: number,
	/**  Rows per block returned by `get_graph_block`. */
	blockRows: number,
	/**  Row of the commit HEAD points to. */
	headRow: number | null,
	/**  Parent links dropped because objects are missing (partial clones). */
	missingParents: number,
	/**  How long building took, in milliseconds. */
	buildMs: number | null,
	/**
	 *  Counts the builds of this session's graph; row numbers of different generations do
	 *  not match, so the frontend keys its caches by it.
	 */
	generation: number,
};

/**  Where HEAD points. */
export type HeadDto = 
/**  On a branch with commits. */
{ kind: "branch"; 
/**  Short branch name. */
name: string } | 
/**  On a branch without commits yet. */
{ kind: "unborn"; 
/**  Short branch name. */
name: string } | 
/**  Detached at a commit. */
{ kind: "detached"; 
/**  Full commit id. */
id: string };

/**  Why the history ends before the file's first commit. */
export type HistoryStopDto = 
/**  64 renames were followed. */
{ kind: "tooManyRenames" } | 
/**  Following a rename needs file contents a partial clone does not have. */
{ kind: "missingContents"; 
/**  The commit (hex) where following stopped. */
commit: string };

/**
 *  Changed lines of one file to stage, unstage or discard, between the versions the diff
 *  showed.
 */
export type LineChangeDto = {
	/**  Path in the working tree. */
	path: string,
	/**
	 *  The old version the diff showed (hex): the index's blob for working tree changes,
	 *  HEAD's for staged ones; `null` when the file was not there.
	 */
	oldId: string | null,
	/**  The new version the diff showed: the working tree file's id, or the staged blob. */
	newId: string,
	/**  Removed lines, by their number in the old version (a range may include context). */
	removed: LineRangeDto[],
	/**  Added lines, by their number in the new version. */
	added: LineRangeDto[],
};

/**  Lines `start..=end` (1-based) of one version of a file. */
export type LineRangeDto = {
	/**  First line. */
	start: number,
	/**  Last line (inclusive). */
	end: number,
};

/**  A version of the file, for finding the row of one of its lines. */
export type LineSideDto = 
/**  Before the change. */
"old" | 
/**  After the change. */
"new";

/**  What a commit did to the path. */
export type PathChangeDto = 
/**  Created it. */
"added" | 
/**  Changed it. */
"modified" | 
/**  Removed it. */
"deleted" | 
/**  Renamed the file to this path (`previousPath` is the old name). */
"renamed" | 
/**  A merge that differs from every parent at the path. */
"merge";

/**  One entry of the list as the UI sees it. */
export type RecentRepository = {
	/**  Work tree (or bare repository) path. */
	path: string,
	/**  Folder name. */
	name: string,
	/**  When it was last opened, seconds since the epoch. */
	lastOpened: number | null,
	/**  Whether the folder still exists (checked when the list is read). */
	exists: boolean,
};

/**  One branch, remote branch or tag, with the row and time of its commit. */
export type RefEntry = {
	/**  Name, category and HEAD marker. */
	label: RefLabel,
	/**  Full id of the commit it points to (annotated tags peeled). */
	target: string,
	/**  Row of that commit, if it is in the graph. */
	row: number | null,
	/**
	 *  Committer time of that commit in seconds since the epoch, for sorting by date; `null`
	 *  when the target is not a commit of the history.
	 */
	commitTime: number | null,
};

/**  Category of a reference label. */
export type RefKindDto = 
/**  Detached HEAD. */
"head" | 
/**  Local branch. */
"branch" | 
/**  Remote-tracking branch. */
"remote" | 
/**  Tag. */
"tag";

/**  A reference label on a row. */
export type RefLabel = {
	/**  Short name (`main`, `origin/main`, `v1.0`). */
	name: string,
	/**  Category. */
	kind: RefKindDto,
	/**  HEAD points here. */
	isHead: boolean,
};

/**  One reference, by kind and short name. */
export type RefSelectorDto = {
	/**  Branch, remote branch or tag. */
	kind: RefKindDto,
	/**  Short name (`main`, `origin/main`, `v1.0`). */
	name: string,
};

/**  The graph after a reload, and where the commit selected before it is now. */
export type ReloadedGraph = {
	/**  The new graph. */
	summary: GraphSummary,
	/**
	 *  Row of the previously selected commit; `None` when it is gone (amended, rebased) or
	 *  nothing was selected.
	 */
	row: number | null,
};

/**  How the repository is laid out on disk. */
export type RepoKindDto = 
/**  Has its own work tree. */
"normal" | 
/**  No work tree. */
"bare" | 
/**  Added with `git worktree add`. */
"linkedWorktree" | 
/**  A submodule. */
"submodule";

/**  An open repository. */
export type RepoSummary = {
	/**  Session id for later commands. */
	id: number,
	/**  Folder name, for tabs. */
	name: string,
	/**  Work tree, or the repository itself when bare. */
	path: string,
	/**  The `.git` directory. */
	gitDir: string,
	/**  Layout on disk. */
	kind: RepoKindDto,
	/**  Where HEAD points. */
	head: HeadDto,
	/**  History cut off by a shallow clone. */
	isShallow: boolean,
	/**  A commit-graph file exists. */
	hasCommitGraph: boolean,
};

/**
 *  Emitted to the main window when repositories were requested (for example by a second
 *  `noblame <path>` launch). The main window then calls `take_repository_requests`.
 */
export type RepositoriesRequested = null;

/**  A section of the Repositories module. */
export type RepositoriesSection = 
/**  Open repositories with their submodules. */
"open" | 
/**  The user's repository groups. */
"groups" | 
/**  Recently opened repositories that are not open. */
"recent";

/**  Repositories module preferences. */
export type RepositoriesSettings = {
	/**  Each repository row has a "…" button with its actions. */
	showActionsMenu?: boolean,
	/**  Order of the module's sections, top to bottom (the UI adds any that are missing). */
	sections?: RepositoriesSection[],
	/**  Sections shown folded. */
	collapsedSections?: RepositoriesSection[],
};

/**
 *  A repository changed outside the app. The frontend reloads the graph (and everything read
 *  from it) for `refs`, and re-reads the status for `workTree`. A missed event is harmless:
 *  the status is also read when the window regains focus.
 */
export type RepositoryChanged = {
	/**  The session. */
	id: number,
	/**  HEAD, a branch, a tag, a remote branch or the stash moved. */
	refs: boolean,
	/**  A file in the working tree or the index changed. */
	workTree: boolean,
};

/**  One group, in the order the user arranged. */
export type RepositoryGroup = {
	/**  Stable id chosen by the UI. */
	id: string,
	/**  Name shown in the module. */
	name: string,
	/**  Whether the group is shown folded. */
	collapsed: boolean,
	/**  Work tree (or bare repository) paths, in the user's order. */
	repositories: string[],
};

/**  The groups as the UI sees them. */
export type RepositoryGroupsDto = {
	/**  The groups, in order. */
	groups: RepositoryGroup[],
	/**  Grouped paths whose folder no longer exists (checked when the list is read). */
	missing: string[],
};

/**
 *  All persisted user preferences. Unknown fields are ignored and missing fields
 *  fall back to defaults, so older and newer app versions can share the file.
 */
export type Settings = {
	/**  Color scheme of every window. */
	theme?: ThemePreference,
	/**  Commit graph. */
	graph?: GraphSettings,
	/**  Repositories module. */
	repositories?: RepositoriesSettings,
	/**  The diff tab. */
	diff?: DiffSettings,
	/**  Branches module. */
	branches?: BranchesSettings,
};

/**  The result of checking a commit's signature. */
export type SignatureCheckDto = {
	/**  What the commit is signed with. */
	format: SignatureFormatDto,
	/**  Whether it verifies. */
	verdict: SignatureVerdictDto,
	/**  Who signed it, when known. */
	signer: string | null,
	/**  The signing key. */
	key: string | null,
	/**  The key's fingerprint. */
	fingerprint: string | null,
	/**  The primary key's fingerprint when a subkey signed. */
	primaryFingerprint: string | null,
	/**  gpg's trust level of the key. */
	trust: string | null,
	/**  What the verifying program (or git) said. */
	message: string,
};

/**  Author or committer. */
export type SignatureDto = {
	/**  Name. */
	name: string,
	/**  E-mail. */
	email: string,
	/**  Seconds since the epoch. */
	time: number | null,
	/**  Time-zone offset in minutes east of UTC. */
	offsetMinutes: number,
};

/**  What a commit is signed with. */
export type SignatureFormatDto = 
/**  PGP (`gpg`). */
"openPgp" | 
/**  SSH (`ssh-keygen`). */
"ssh" | 
/**  X.509 (`gpgsm`). */
"x509" | 
/**  Not recognised. */
"unknown";

/**  Whether the signature verifies (git's `%G?`). */
export type SignatureVerdictDto = 
/**  Good, from a trusted key. */
"good" | 
/**  Good, but the key is not trusted or not an allowed signer. */
"unknownValidity" | 
/**  Good, but the signature has expired. */
"expired" | 
/**  Good, made by a key that has expired. */
"expiredKey" | 
/**  Good, made by a key that has been revoked. */
"revokedKey" | 
/**  Does not match the commit. */
"bad" | 
/**  Could not be checked (missing key, no allowed signers, missing program). */
"cannotCheck";

/**  One side of a side-by-side row. */
export type SplitCellDto = {
	/**  `context`, `removed` (left) or `added` (right). */
	kind: DiffLineKindDto,
	/**  1-based line number on this side. */
	line: number,
	/**  The line without its line ending (non-UTF-8 bytes replaced). */
	text: string,
	/**  The line was cut at 4,096 bytes. */
	truncated: boolean,
	/**  The last line of this side, without a newline at the end. */
	noNewline: boolean,
	/**  Changed words: `[start, end)` in UTF-16 code units. */
	highlights: ([number, number])[],
	/**  Syntax colours: `[start, end, class]` in UTF-16 code units. */
	syntax: ([number, number, SyntaxClassDto])[],
};

/**  One side-by-side row: a hunk header, or a line on the left, the right or both. */
export type SplitLineDto = {
	/**  `@@ -1,3 +1,4 @@` for a hunk header (the cells are then `null`). */
	hunk: string | null,
	/**  Old version. */
	left: SplitCellDto | null,
	/**  New version. */
	right: SplitCellDto | null,
};

/**  One stash, newest first. */
export type StashDto = {
	/**  `n` in `stash@{n}`. */
	index: number,
	/**  Full id of the stash commit. */
	id: string,
	/**  Message as `git stash list` shows it. */
	message: string,
	/**  Branch it was made on, if known. */
	branch: string | null,
	/**  When it was made, seconds since the epoch. */
	time: number | null,
};

/**  The files of one stash. */
export type StashFilesDto = {
	/**  The commit it was made on (hex). */
	base: string,
	/**  Tracked files it changed, against `base`, sorted by path (at most 5,000). */
	changed: ChangedFileDto[],
	/**  All changed tracked files. */
	changedTotal: number,
	/**  Untracked files it saved (each added), sorted by path (at most 5,000). */
	untracked: ChangedFileDto[],
	/**  All untracked files. */
	untrackedTotal: number,
};

/**  A stash made on a commit, labelled on that commit's row. */
export type StashLabel = {
	/**  `n` in `stash@{n}`. */
	index: number,
	/**  The message as `git stash list` shows it. */
	message: string,
};

/**  Changes to stash. */
export type StashRequestDto = {
	/**  The stash's message; git's `WIP on <branch>: …` when empty. */
	message: string,
	/**  Leave the staged changes in the working tree and the index too. */
	keepIndex: boolean,
	/**  Stash new files as well (they are deleted from the working tree). */
	includeUntracked: boolean,
	/**  Only these files (both names of a rename); `null`: every change. */
	paths: string[] | null,
};

/**  The stash the user chose: `stash@{index}`, checked to still be `id` before anything runs. */
export type StashTargetDto = {
	/**  `n` in `stash@{n}`. */
	index: number,
	/**  The stash commit's full id (hex). */
	id: string,
};

/**  Number of files in each state; a file staged and changed again counts in both. */
export type StatusSummaryDto = {
	/**  Changes in the index. */
	staged: number,
	/**  Tracked files changed in the working tree, not staged. */
	unstaged: number,
	/**  Untracked files. */
	untracked: number,
	/**  Files with merge conflicts. */
	conflicted: number,
};

/**  A submodule and its own submodules. */
export type SubmoduleDto = {
	/**  Name from `.gitmodules`. */
	name: string,
	/**  Path inside the superproject (`/` separators). */
	path: string,
	/**  Absolute path of its work tree. */
	workDir: string,
	/**  Configured URL. */
	url: string | null,
	/**  Cloned and checked out. */
	initialized: boolean,
	/**  Nested submodules. */
	children: SubmoduleDto[],
};

/**  What a coloured part of a line is. */
export type SyntaxClassDto = 
/**  A comment. */
"comment" | 
/**  A string or character literal. */
"string" | 
/**  A keyword or storage modifier. */
"keyword" | 
/**  A number or language constant. */
"constant" | 
/**  A type name. */
"type" | 
/**  A function name. */
"function" | 
/**  A markup tag. */
"tag" | 
/**  A markup attribute name. */
"attribute";

/**  A focused task window. Also the list of `noblame` subcommands (ADR 0015). */
export type TaskKind = 
/**  Commit graph and history. */
"log" | 
/**  Stage changes and commit. */
"commit" | 
/**  Working tree changes. */
"diff" | 
/**  Line-by-line authorship of a file. */
"blame" | 
/**  History of one file. */
"fileHistory" | 
/**  Pull from a remote. */
"pull" | 
/**  Push to a remote. */
"push" | 
/**  Fetch from remotes. */
"fetch" | 
/**  Switch branches. */
"switch" | 
/**  Merge a branch. */
"merge" | 
/**  Rebase the current branch. */
"rebase" | 
/**  Save or restore stashed changes. */
"stash" | 
/**  Clone a repository. */
"clone" | 
/**  Create a repository. */
"init";

/**  Which color scheme the UI uses. */
export type ThemePreference = 
/**  Follow the operating system setting. */
"system" | 
/**  Always light. */
"light" | 
/**  Always dark. */
"dark";

/**  Whose history the tab shows. */
export type TipsDto = 
/**  Every branch, remote branch and tag. */
{ type: "all" } | 
/**  The commit HEAD points to (the current branch). */
{ type: "head" } | 
/**  The given references. */
{ type: "refs"; 
/**  The references. */
refs: RefSelectorDto[] };

/**  One entry of a folder. The name is for display (non-UTF-8 bytes are replaced). */
export type TreeEntryDto = {
	/**  Name in its folder (empty for the root folder). */
	name: string,
	/**  What it is. */
	kind: TreeEntryKindDto,
	/**  Tree, blob or commit id (hex). */
	id: string,
};

/**  What a tree entry is. */
export type TreeEntryKindDto = 
/**  A folder. */
"folder" | 
/**  A file. */
"file" | 
/**  A file with the executable bit. */
"executable" | 
/**  A symbolic link (its contents are the target path). */
"symlink" | 
/**  A submodule (`id` is its commit). */
"submodule";

/**  The entries of one folder. */
export type TreeListingDto = {
	/**  Folders first, then files, by name ignoring case; at most 50,000. */
	entries: TreeEntryDto[],
	/**  All entries, including those not listed. */
	total: number,
};

/**  Which whitespace changes the diff shows, as git's options name them. */
export type WhitespaceMode = 
/**  Every change. */
"show" | 
/**  Not whitespace at the end of lines (`--ignore-space-at-eol`). */
"ignoreAtEol" | 
/**  Not changes in the amount of whitespace (`-b`). */
"ignoreChange" | 
/**  No whitespace at all (`-w`). */
"ignoreAll";

/**  What a window is for. Each window asks for its own context when it starts. */
export type WindowContext = 
/**  The main window with repository tabs. */
{ kind: "main" } | 
/**  A focused task window. */
{ kind: "task"; 
/**  Which task the window shows. */
task: TaskKind; 
/**  Repository, folder or file the task is about. */
path: string };

/**  One file of the status. Paths are for display (non-UTF-8 bytes are replaced). */
export type WorkingFileDto = {
	/**  Path in the working tree; ends in `/` for an untracked folder git does not look into. */
	path: string,
	/**  Old name of a rename or copy. */
	previousPath: string | null,
	/**  What happened to it. */
	status: WorkingStatusDto,
	/**
	 *  The blob it is compared with (hex): `HEAD`'s for staged files, the index's for changed
	 *  ones, "ours" for conflicts; `null` when absent there.
	 */
	oldId: string | null,
	/**  The staged blob (hex), for staged files; `null` otherwise. */
	newId: string | null,
	/**  The new version is the file in the working tree (`get_worktree_file_id` names it). */
	worktree: boolean,
	/**  A submodule pointer, not a file. */
	submodule: boolean,
};

/**  What happened to a file on one side of the status. */
export type WorkingStatusDto = 
/**  New file. */
"added" | 
/**  Removed. */
"deleted" | 
/**  Content, mode or type changed. */
"modified" | 
/**  Moved (`previousPath` is the old name). */
"renamed" | 
/**  Copied from `previousPath`. */
"copied" | 
/**  Not tracked by git. */
"untracked" | 
/**  Has merge conflicts. */
"conflicted";

/**  Where the working tree changes (staged, unstaged, untracked, conflicted) are shown. */
export type WorkingTreeDisplay = 
/**  Rows at the top of the commit graph, as Git Extensions does. */
"rows" | 
/**  A summary in the repository header. */
"header" | 
/**  Not shown. */
"hidden";

/**  The working tree status: counts of everything, and the files (at most 5,000 on each side). */
export type WorkingTreeStatusDto = {
	/**  How many files are in each state. */
	summary: StatusSummaryDto,
	/**  Staged changes, sorted by path. */
	staged: WorkingFileDto[],
	/**  Changed, untracked and conflicted files, sorted by path. */
	unstaged: WorkingFileDto[],
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

type EventEmitTo<T> = [T] extends [null] ? (target: __TAURI_EVENT.EventTarget | string) => Promise<void> : (target: __TAURI_EVENT.EventTarget | string, payload: T) => Promise<void>;

function makeEvent<TListen, TEmit = TListen>(name: string, serialize?: (payload: TEmit) => unknown, deserialize?: (payload: any) => TListen) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<TListen>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: TEmit) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<TListen>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<TListen>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: TEmit) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<TEmit>,
        emitTo: ((to: __TAURI_EVENT.EventTarget | string, payload: TEmit) => __TAURI_EVENT.emitTo(to, name, mapPayload(payload)) as unknown) as EventEmitTo<TEmit>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<TListen>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<TListen>) => target.once(name, mapEvent(cb)),
        emit: ((payload: TEmit) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<TEmit>,
        emitTo: ((to: __TAURI_EVENT.EventTarget | string, payload: TEmit) => target.emitTo(to, name, mapPayload(payload)) as unknown) as EventEmitTo<TEmit>
    });

    return Object.assign(fn, base);
}

